import json
A='/private/tmp/opensip-design-corrections/claude-independent-design.v40/receipts/reference/evaluator3/'
B='/Users/sb/code/opensip-ai/opensip_arch/docs/coop/design-corrections/reviews/codex-post-reset.v1/final-reference.v40/evaluator3/'
def diff(a,b,p=''):
  if type(a)!=type(b): return [p]
  if isinstance(a,dict): return sum((diff(a.get(k),b.get(k),p+'/'+k) for k in sorted(set(a)|set(b))),[])
  if isinstance(a,list): return [p+'[len]'] if len(a)!=len(b) else sum((diff(x,y,p+'/'+str(i)) for i,(x,y) in enumerate(zip(a,b))),[])
  return [] if a==b else [p]
for n in ['enumeration.stdout','execution-inputs.stdout']:
  x=json.load(open(A+n)); y=json.load(open(B+n)); d=diff(x,y)
  print(n,len(d),d[:12])
  for p in d[:4]:
    cur_x,cur_y=x,y
    for k in [s for s in p.split('/') if s]:
      k2=int(k) if k.isdigit() else k; cur_x=cur_x[k2]; cur_y=cur_y[k2]
    print('  ',p,'mine=',str(cur_x)[:160],'codex=',str(cur_y)[:160])
"

