def latest_run(name):
    runs = sorted(glob.glob(REC + '/runs/' + name + '.run.json') + glob.glob(REC + '/runs/' + name + '.attempt*.run.json'),
                  key=lambda p: int(re.search(r'attempt(\d+)', p).group(1)) if 'attempt' in p else 1)
    return runs


def run_record(name, script):
    runs = latest_run(name)
    if not runs:
        GAPS.append('no run receipt: ' + name)
        return None
    last = J(runs[-1])
    cur = sha(script)
    ok = last['exitCode'] == 0 and not last['copyChangedVsManifest'] and not last['copyExtraVsManifest'] and last['scriptSha256'] == cur
    if not ok:
        GAPS.append('run receipt not clean or script changed after the latest run: ' + name)
    return {'runReceipt': rel(runs[-1]), 'runReceiptSha256': sha(runs[-1]), 'exitCode': last['exitCode'], 'seconds': last['seconds'],
            'scriptSha256': last['scriptSha256'], 'scriptUnchangedSinceRun': last['scriptSha256'] == cur, 'copyUnchanged': not last['copyChangedVsManifest'],
            'earlierAttempts': [rel(p) for p in runs[:-1]]}


